    expect((await run(database, ["list", "--tag", "WORK"])).value.map((task: any) => task.id)).toEqual([1]);
    expect((await run(database, ["list", "--overdue", "2000-01-02"])).value.map((task: any) => task.id)).toEqual([1]);

    const done = await run(database, ["done", "1"]);
    const completedAt = done.value.completedAt;
    expect(done.value.status).toBe("done");
    expect((await run(database, ["done", "1"])).value.completedAt).toBe(completedAt);
    expect((await run(database, ["delete", "2"])).value.id).toBe(2);
    expect((await run(database, ["add", "--title", "Third"])).value.id).toBe(3);
  });

  test("stats and AND-combined list filters are correct", async () => {
    const { database } = await workspace();
    await run(database, ["add", "--title", "Late", "--tags", "x", "--due", "2000-01-01"]);
    await run(database, ["add", "--title", "Done", "--tags", "x", "--due", "2000-01-01"]);
    await run(database, ["done", "2"]);
    expect((await run(database, ["list", "--status", "open", "--tag", "x", "--overdue", "2001-01-01"])).value).toHaveLength(1);
    expect((await run(database, ["stats"])).value).toEqual({ total: 2, open: 1, done: 1, overdue: 1 });
  });

  test("rejects invalid input and preserves malformed data", async () => {
    const { database } = await workspace();
    const invalidDate = await run(database, ["add", "--title", "Bad", "--due", "2025-02-30"]);
    expect(invalidDate.exitCode).not.toBe(0);
    expect(invalidDate.stderr).toContain("valid YYYY-MM-DD");
    expect(invalidDate.stdout.trim().split("\n")).toHaveLength(1);

    const original = "{broken json\n";
    await writeFile(database, original);
    const malformed = await run(database, ["add", "--title", "No overwrite"]);
    expect(malformed.exitCode).not.toBe(0);
    expect(malformed.value.error).toContain("malformed database");
    expect(await readFile(database, "utf8")).toBe(original);

    expect((await run(database, ["wat"])).exitCode).not.toBe(0);
  });
});
